final class Sesion {
    let nombre: String
    init(_ nombre: String) { self.nombre = nombre; print("  nace \(nombre)") }
    deinit { print("  muere \(nombre)") }
}

print("--- dos referencias a la misma instancia")
var a: Sesion? = Sesion("A")
var b = a
a = nil                          // queda b: el contador baja de 2 a 1
print("  a = nil (todavia viva)")
b = nil                          // el contador llega a 0: se libera aca
print("  b = nil")

final class Padre  { var hijo: Hijo?;  deinit { print("  muere Padre") } }
final class Hijo   { var padre: Padre?; deinit { print("  muere Hijo") } }
print("--- ciclo fuerte")
do { let p = Padre(); let h = Hijo(); p.hijo = h; h.padre = p }
print("  salimos del bloque: nadie murio")

final class Padre2 { var hijo: Hijo2?;  deinit { print("  muere Padre2") } }
final class Hijo2  { weak var padre: Padre2?; deinit { print("  muere Hijo2") } }
print("--- ciclo con weak")
var hijoSuelto: Hijo2? = Hijo2()
do { let p = Padre2(); p.hijo = hijoSuelto; hijoSuelto!.padre = p
     print("  adentro, padre es nil?", hijoSuelto!.padre == nil) }
print("  afuera, padre es nil?", hijoSuelto!.padre == nil)
